CREATE TABLE "patients" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"auth_account_id" UUID,"full_name" VARCHAR(150) NOT NULL,"normalized_full_name" VARCHAR(150) NOT NULL,"date_of_birth" DATE NOT NULL,"phone_number" VARCHAR(16) NOT NULL,"national_id_ciphertext" TEXT,"national_id_lookup_hash" CHAR(64),"address" VARCHAR(500),"version" INTEGER NOT NULL DEFAULT 1,"created_by_account_id" UUID NOT NULL,"updated_by_account_id" UUID NOT NULL,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "patients_pkey" PRIMARY KEY ("id"));
CREATE TABLE "emergency_contacts" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"patient_id" UUID NOT NULL,"full_name" VARCHAR(150) NOT NULL,"relationship" VARCHAR(50) NOT NULL,"phone_number" VARCHAR(16) NOT NULL,"is_primary" BOOLEAN NOT NULL DEFAULT false,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "emergency_contacts_pkey" PRIMARY KEY ("id"));
CREATE TABLE "patient_audit_logs" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"event_type" VARCHAR(50) NOT NULL,"actor_id" UUID NOT NULL,"actor_role" VARCHAR(30) NOT NULL,"patient_id" UUID NOT NULL,"changed_fields" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],"request_id" UUID NOT NULL,"metadata" JSONB,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "patient_audit_logs_pkey" PRIMARY KEY ("id"));
CREATE TABLE "idempotency_records" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"actor_id" UUID NOT NULL,"operation" VARCHAR(80) NOT NULL,"idempotency_key" UUID NOT NULL,"request_hash" CHAR(64) NOT NULL,"patient_id" UUID,"status" VARCHAR(20) NOT NULL,"expires_at" TIMESTAMPTZ(6) NOT NULL,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "idempotency_records_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "patients_auth_account_id_key" ON "patients"("auth_account_id"); CREATE UNIQUE INDEX "patients_national_id_lookup_hash_key" ON "patients"("national_id_lookup_hash"); CREATE INDEX "patients_phone_number_idx" ON "patients"("phone_number"); CREATE INDEX "patients_normalized_full_name_idx" ON "patients"("normalized_full_name"); CREATE INDEX "emergency_contacts_patient_id_idx" ON "emergency_contacts"("patient_id"); CREATE UNIQUE INDEX "emergency_contacts_one_primary_key" ON "emergency_contacts"("patient_id") WHERE "is_primary" = true; CREATE INDEX "patient_audit_logs_patient_created_idx" ON "patient_audit_logs"("patient_id", "created_at"); CREATE INDEX "patient_audit_logs_actor_created_idx" ON "patient_audit_logs"("actor_id", "created_at"); CREATE UNIQUE INDEX "idempotency_records_actor_operation_key" ON "idempotency_records"("actor_id", "operation", "idempotency_key"); CREATE INDEX "idempotency_records_expires_at_idx" ON "idempotency_records"("expires_at");
ALTER TABLE "emergency_contacts" ADD CONSTRAINT "emergency_contacts_patient_id_fkey" FOREIGN KEY ("patient_id") REFERENCES "patients"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "patient_audit_logs" ADD CONSTRAINT "patient_audit_logs_patient_id_fkey" FOREIGN KEY ("patient_id") REFERENCES "patients"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
